CustomField.formula:
DATETIMEVALUE(
Text(Website_Go_Live_Date__c)&" "&
  if(Text(Website_Go_Live_Time_Manual__c)="TBD" || Text(Website_Go_Live_Time_Manual__c)="", "00:01:00",
  Text(
      (Value(Mid(Text(Website_Go_Live_Time_Manual__c), 1, Find(":", Text(Website_Go_Live_Time_Manual__c))-1))+
	  if(Find("PM", Text(Website_Go_Live_Time_Manual__c))>0, 12, 0))
  )&":"&
  Mid(Text(Website_Go_Live_Time_Manual__c), Find(":", Text(Website_Go_Live_Time_Manual__c))+1, 2)&":00"
))
